/**
 * The machine recipe classes of an ejected project (ADR 0075 D11), in `<package>/recipe/`: copies
 * of the runtime's `MsmMachineRecipe`, `MachineInput` and `MachineRecipes`
 * (`engine-mod/src/main/java/dev/mcsupermods/runtime/registry/machine/`, Minecraft 26.3, Mojang
 * names). The recipe's codec is written out with vanilla's `RecordCodecBuilder` (the runtime
 * shares its fields with the JUnit corpus through `MachineRecipeFormat`, which is not ejected);
 * the ranges are the same. The generator's tests compare every other code line with the
 * runtime's.
 *
 * @packageDocumentation
 */

import { javaString } from '../java';

/** The source of `MachineRecipe.java`, copied from the runtime's `MsmMachineRecipe`. */
export function machineRecipeJava(recipePackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's MsmMachineRecipe.
package ${recipePackage};

import com.mojang.serialization.Codec;
import com.mojang.serialization.MapCodec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import java.util.List;
import java.util.Optional;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.ItemStackTemplate;
import net.minecraft.world.item.crafting.Ingredient;
import net.minecraft.world.item.crafting.PlacementInfo;
import net.minecraft.world.item.crafting.Recipe;
import net.minecraft.world.item.crafting.RecipeBookCategories;
import net.minecraft.world.item.crafting.RecipeBookCategory;
import net.minecraft.world.item.crafting.RecipeSerializer;
import net.minecraft.world.item.crafting.RecipeType;
import net.minecraft.world.item.crafting.display.RecipeDisplay;
import net.minecraft.world.level.Level;

/**
 * A machine recipe (ADR 0075 D2): {@code count} of {@code ingredient} from the input slot make {@code result} after
 * {@code time} ticks at speed 1 (absent: the machine's {@code default_time}), storing {@code experience}. Its type and
 * serialiser are the machine's ({@link MachineRecipes.Kind}). Not shown in the recipe book: {@link #display()} is empty
 * (limit C11), the category {@code FURNACE_MISC}, no unlock notification.
 */
public final class MachineRecipe implements Recipe<MachineInput> {
    /** The highest {@code time}: menu data is 16-bit (limit C5). */
    public static final int MAX_TIME = 32767;

    private final MachineRecipes.Kind kind;
    private final Ingredient ingredient;
    private final int count;
    private final ItemStackTemplate result;
    private final Optional<Integer> time;
    private final float experience;
    private PlacementInfo placementInfo;

    public MachineRecipe(MachineRecipes.Kind kind, Ingredient ingredient, int count, ItemStackTemplate result,
            Optional<Integer> time, float experience) {
        this.kind = kind;
        this.ingredient = ingredient;
        this.count = count;
        this.result = result;
        this.time = time;
        this.experience = experience;
    }

    /**
     * The data pack codec of {@code kind}'s recipes: vanilla's ingredient and result shapes, {@code count} 1 to 64
     * (default 1), {@code time} 1 to 32767 (absent: the machine's {@code default_time}), {@code experience} at least 0
     * (default 0). {@code type} is read by vanilla's recipe dispatch.
     */
    static MapCodec<MachineRecipe> codec(MachineRecipes.Kind kind) {
        return RecordCodecBuilder.mapCodec(i -> i.group(
                Ingredient.CODEC.fieldOf("ingredient").forGetter(MachineRecipe::ingredient),
                Codec.intRange(1, 64).optionalFieldOf("count", 1).forGetter(MachineRecipe::count),
                ItemStackTemplate.MAP_CODEC.codec().fieldOf("result").forGetter(MachineRecipe::result),
                Codec.intRange(1, MAX_TIME).optionalFieldOf("time").forGetter(MachineRecipe::time),
                Codec.floatRange(0.0f, Float.MAX_VALUE).optionalFieldOf("experience", 0.0f).forGetter(MachineRecipe::experience))
                .apply(i, (ingredient, count, result, time, experience) -> new MachineRecipe(kind, ingredient, count, result, time, experience)));
    }

    /** The network codec of {@code kind}'s recipes (registry sync completeness; 26.x sends recipes to no client). */
    static StreamCodec<RegistryFriendlyByteBuf, MachineRecipe> streamCodec(MachineRecipes.Kind kind) {
        return StreamCodec.composite(
                Ingredient.CONTENTS_STREAM_CODEC, MachineRecipe::ingredient,
                ByteBufCodecs.VAR_INT, MachineRecipe::count,
                ItemStackTemplate.STREAM_CODEC, MachineRecipe::result,
                ByteBufCodecs.optional(ByteBufCodecs.VAR_INT), MachineRecipe::time,
                ByteBufCodecs.FLOAT, MachineRecipe::experience,
                (ingredient, count, result, time, experience) -> new MachineRecipe(kind, ingredient, count, result, time, experience));
    }

    public Ingredient ingredient() {
        return ingredient;
    }

    public int count() {
        return count;
    }

    public ItemStackTemplate result() {
        return result;
    }

    public Optional<Integer> time() {
        return time;
    }

    public float experience() {
        return experience;
    }

    /** The machine whose recipe type this is. */
    public MachineRecipes.Kind kind() {
        return kind;
    }

    /** The input slot holds at least {@code count} of the ingredient. */
    @Override
    public boolean matches(MachineInput input, Level level) {
        ItemStack stack = input.item();
        return !stack.isEmpty() && stack.getCount() >= count && ingredient.test(stack);
    }

    @Override
    public ItemStack assemble(MachineInput input) {
        return result.create();
    }

    @Override
    public boolean showNotification() {
        return false;
    }

    @Override
    public String group() {
        return "";
    }

    @Override
    public RecipeSerializer<MachineRecipe> getSerializer() {
        return kind.serializer();
    }

    @Override
    public RecipeType<MachineRecipe> getType() {
        return kind.type();
    }

    @Override
    public PlacementInfo placementInfo() {
        if (placementInfo == null) {
            placementInfo = PlacementInfo.create(ingredient);
        }
        return placementInfo;
    }

    @Override
    public List<RecipeDisplay> display() {
        return List.of();
    }

    @Override
    public RecipeBookCategory recipeBookCategory() {
        return RecipeBookCategories.FURNACE_MISC;
    }
}
`;
}

/** The source of `MachineInput.java`, copied from the runtime's `MachineInput`. */
export function machineInputJava(recipePackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's MachineInput.
package ${recipePackage};

import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.RecipeInput;

/** The input of a machine recipe (ADR 0075 D2): the input slot's stack, with its count. */
public record MachineInput(ItemStack item) implements RecipeInput {
    @Override
    public ItemStack getItem(int index) {
        if (index != 0) {
            throw new IllegalArgumentException("a machine input has one slot, not " + index);
        }
        return item;
    }

    @Override
    public int size() {
        return 1;
    }
}
`;
}

/** The source of `MachineRecipes.java`, copied from the runtime's `MachineRecipes`. */
export function machineRecipesJava(
  recipePackage: string,
  blockPackage: string,
  modId: string,
): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's MachineRecipes.
package ${recipePackage};

import ${blockPackage}.MachineSpec;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import net.minecraft.core.Registry;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.AbstractCookingRecipe;
import net.minecraft.world.item.crafting.Recipe;
import net.minecraft.world.item.crafting.RecipeHolder;
import net.minecraft.world.item.crafting.RecipeManager;
import net.minecraft.world.item.crafting.RecipeSerializer;
import net.minecraft.world.item.crafting.RecipeType;
import net.minecraft.world.item.crafting.SingleRecipeInput;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Per-machine recipe types and serialisers (ADR 0075 D2, limit C1) and the lookups a machine runs.
 *
 * <p>{@link #register} registers, for one machine, a {@link RecipeType} (an anonymous implementation whose
 * {@code toString} is the id, as vanilla's) and a {@link RecipeSerializer} with the machine block's id, through
 * {@code Registry.register} (never {@code RecipeType.register(String)}, which always takes the {@code minecraft}
 * namespace). A machine's {@code recipe_types} are resolved on first use, after every definition is registered: a
 * machine's own id or another machine's, or one of the four vanilla cooking types; anything else is logged once and
 * skipped.
 */
public final class MachineRecipes {
    private static final Map<Identifier, Kind> KINDS = new ConcurrentHashMap<>();
    private static final Set<String> LOGGED = ConcurrentHashMap.newKeySet();
    private static final String MOD_ID = ${javaString(modId)};
    private static final Logger LOGGER = LoggerFactory.getLogger(MOD_ID);

    private MachineRecipes() {}

    /** One machine's recipe type and serialiser, both with the machine block's id. */
    public static final class Kind {
        private final Identifier id;
        private final RecipeType<MachineRecipe> type;
        private final RecipeSerializer<MachineRecipe> serializer;

        private Kind(Identifier id) {
            this.id = id;
            this.type = new RecipeType<>() {
                @Override
                public String toString() {
                    return id.toString();
                }
            };
            this.serializer = new RecipeSerializer<>(MachineRecipe.codec(this), MachineRecipe.streamCodec(this));
        }

        public Identifier id() {
            return id;
        }

        public RecipeType<MachineRecipe> type() {
            return type;
        }

        public RecipeSerializer<MachineRecipe> serializer() {
            return serializer;
        }
    }

    /**
     * Whether {@code id} is free in both the recipe type and the recipe serialiser registries, so {@link #register} can
     * take it.
     */
    public static boolean isFree(Identifier id) {
        return !BuiltInRegistries.RECIPE_TYPE.containsKey(id) && !BuiltInRegistries.RECIPE_SERIALIZER.containsKey(id);
    }

    /** Registers the recipe type and serialiser of the machine {@code id}; the caller checked {@link #isFree}. */
    public static Kind register(Identifier id) {
        Kind kind = new Kind(id);
        Registry.register(BuiltInRegistries.RECIPE_TYPE, id, kind.type);
        Registry.register(BuiltInRegistries.RECIPE_SERIALIZER, id, kind.serializer);
        KINDS.put(id, kind);
        return kind;
    }

    /** The machine recipe kind registered with {@code id}, if any. */
    public static Optional<Kind> kind(Identifier id) {
        return Optional.ofNullable(KINDS.get(id));
    }

    /**
     * A recipe found for the input: the holder, the inputs it uses, the assembled result, its own time (absent: the
     * machine's {@code default_time}) and its experience.
     */
    public record Match(RecipeHolder<?> recipe, int count, ItemStack result, Optional<Integer> time, float experience) {}

    /** The recipes of one accepted type, with the furnace's cached check (one per block entity). */
    public interface Lookup {
        /** The first recipe of this type for {@code input}, through {@link RecipeManager#createCheck}. */
        Optional<Match> find(ItemStack input, ServerLevel level);

        /** Whether any recipe of this type takes {@code stack} (its count ignored): shift-click into the input slot. */
        boolean accepts(ItemStack stack, ServerLevel level);
    }

    /**
     * Fresh lookups for the machine {@code machine}, one per entry of {@code types} that resolves; the order is kept, so
     * the first type with a match wins.
     */
    public static List<Lookup> lookups(Identifier machine, List<Identifier> types) {
        List<Lookup> out = new ArrayList<>();
        for (Identifier id : types) {
            Optional<Kind> kind = kind(id);
            if (kind.isPresent()) {
                out.add(machineLookup(kind.get().type()));
            } else if (MachineSpec.COOKING_TYPES.contains(id) && BuiltInRegistries.RECIPE_TYPE.getValue(id) != null) {
                out.add(cookingLookup(BuiltInRegistries.RECIPE_TYPE.getValue(id)));
            } else if (LOGGED.add(machine + " " + id)) {
                LOGGER.error("[{}] {}: msm:machine: recipe_types: {} is neither a machine's id nor a vanilla cooking"
                        + " recipe type; it is skipped", MOD_ID, machine, id);
            }
        }
        return List.copyOf(out);
    }

    private static Lookup machineLookup(RecipeType<MachineRecipe> type) {
        RecipeManager.CachedCheck<MachineInput, MachineRecipe> check = RecipeManager.createCheck(type);
        return new Lookup() {
            @Override
            public Optional<Match> find(ItemStack input, ServerLevel level) {
                MachineInput in = new MachineInput(input);
                return check.getRecipeFor(in, level).map(h -> new Match(h, h.value().count(), h.value().assemble(in),
                        h.value().time(), h.value().experience()));
            }

            @Override
            public boolean accepts(ItemStack stack, ServerLevel level) {
                return anyTakes(type, stack, level);
            }
        };
    }

    @SuppressWarnings("unchecked")
    private static Lookup cookingLookup(RecipeType<?> raw) {
        RecipeType<AbstractCookingRecipe> type = (RecipeType<AbstractCookingRecipe>) raw; // one of the four cooking types
        RecipeManager.CachedCheck<SingleRecipeInput, AbstractCookingRecipe> check = RecipeManager.createCheck(type);
        return new Lookup() {
            @Override
            public Optional<Match> find(ItemStack input, ServerLevel level) {
                SingleRecipeInput in = new SingleRecipeInput(input);
                return check.getRecipeFor(in, level).map(h -> new Match(h, 1, h.value().assemble(in),
                        Optional.of(h.value().cookingTime()), h.value().experience()));
            }

            @Override
            public boolean accepts(ItemStack stack, ServerLevel level) {
                return anyTakes(type, stack, level);
            }
        };
    }

    private static boolean anyTakes(RecipeType<?> type, ItemStack stack, ServerLevel level) {
        for (RecipeHolder<?> holder : level.recipeAccess().getRecipes()) {
            Recipe<?> recipe = holder.value();
            if (recipe.getType() == type && recipe.placementInfo().ingredients().stream().anyMatch(i -> i.test(stack))) {
                return true;
            }
        }
        return false;
    }
}
`;
}
